'use client'

import { decisionAction, type OrluneAction } from './action'
import { viewDigest } from '../verify/receipt'
import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from 'react'
import { cannotDecide, DEFAULT_ALLOWED, judgeItem, planDigest, RISK_ORDER, STATUS_ORDER, type Decision, type DecisionKind, type ItemStatus, type QueueItem } from './approval'
import { formatDuration } from './chart'
import { Check, Cross } from './icons'
import { JsonTree } from './JsonTree'
import { after } from './theatre'
import { ReviewActions } from './ReviewActions'
import { cx, formatWhen } from './util'

export type { QueueItem, Decision, DecisionKind }
export type ApprovalQueueProps = {
  title: string
  items: QueueItem[]
  /** Who is looking. They cannot decide their own requests or decide twice. */
  reviewer: string
  now?: string | Date
  /** Hide other reviewers' decisions until this reviewer has decided, so a second approval is an independent one. */
  blind?: boolean
  onDecide?: (id: string, decision: DecisionKind, planHash: string, message?: string) => void
  /** The same decision as one action a model can be told about: see `toToolOutput` and `toModelContext`. */
  onAction?: (action: OrluneAction) => void
  /** With `requireView`, a request cannot be decided until its id has an entry here: the data hash of the receipt that says it was shown to this reviewer. */
  receipts?: Record<string, string>
  /** No decision until what the reviewer saw has been recorded. */
  requireView?: boolean
  /** Called with the edited plan when a reviewer saves a change to it. The plan, and so the hash every approval is bound to, is now the new one. */
  onEdit?: (id: string, plan: unknown) => void
  defaultSelected?: string
  /** Called with the id of the request being shown, including the first one on load. */
  onSelect?: (id: string) => void
  className?: string
}

const STATUS_WORD: Record<ItemStatus, { text: string; tone?: 'good' | 'warn' | 'bad' }> = {
  pending: { text: 'Waiting', tone: 'warn' }, partial: { text: 'Needs another approval', tone: 'warn' }, approved: { text: 'Approved', tone: 'good' },
  rejected: { text: 'Rejected', tone: 'bad' }, escalated: { text: 'Escalated', tone: 'good' }, responded: { text: 'Answered, nothing ran', tone: 'warn' }, expired: { text: 'Expired', tone: 'bad' }, stale: { text: 'Plan changed', tone: 'bad' },
}

/**
 * A review queue where an approval is bound to the exact plan. The plan is hashed, every decision records the
 * hash it was made on, and a decision on an older version stops counting the moment the plan changes. Buttons
 * say what will happen, the page says whether it can be undone and what evidence was checked, a second
 * approval must come from a different person, and anything not decided in time expires instead of going through.
 */
export function ApprovalQueue({ title, items, reviewer, now, blind = false, onDecide, onAction, receipts, requireView = false, onEdit, defaultSelected, onSelect, className }: ApprovalQueueProps) {
  const clock = now ? new Date(now) : new Date()
  const [hashes, setHashes] = useState<Record<string, string>>({})
  const [local, setLocal] = useState<Record<string, Decision[]>>({})
  const [selected, setSelected] = useState<string | undefined>(defaultSelected ?? items[0]?.id)
  const [edits, setEdits] = useState<Record<string, unknown>>({})
  const body = useRef<HTMLDivElement>(null)
  const seenPlans = useRef<Record<string, unknown>>({})

  // When the host hands back a different plan for an item, its own version wins over a local edit.
  useEffect(() => {
    const changed = items.filter((i) => i.id in seenPlans.current && seenPlans.current[i.id] !== i.plan).map((i) => i.id)
    seenPlans.current = Object.fromEntries(items.map((i) => [i.id, i.plan]))
    if (changed.length) setEdits((e) => Object.fromEntries(Object.entries(e).filter(([id]) => !changed.includes(id))))
  }, [items])

  const planned = useMemo(() => items.map((i) => (i.id in edits ? { ...i, plan: edits[i.id] } : i)), [items, edits])
  useEffect(() => {
    let live = true
    Promise.all(planned.map(async (i) => [i.id, await planDigest(i.plan)] as const)).then((pairs) => { if (live) setHashes(Object.fromEntries(pairs)) })
    return () => { live = false }
  }, [planned])

  const full = useMemo(() => planned.map((i) => ({ ...i, decisions: [...i.decisions, ...(local[i.id] ?? [])] })), [planned, local])
  const rows = full.map((item) => ({ item, hash: hashes[item.id], judged: hashes[item.id] ? judgeItem(item, hashes[item.id]!, clock) : null }))
  const ordered = [...rows].sort((a, b) => (a.judged ? STATUS_ORDER[a.judged.status] : 1) - (b.judged ? STATUS_ORDER[b.judged.status] : 1) || RISK_ORDER[a.item.risk] - RISK_ORDER[b.item.risk])
  const cur = ordered.find((r) => r.item.id === selected) ?? ordered[0]
  const shownId = cur?.item.id
  useEffect(() => { if (shownId) onSelect?.(shownId) }, [shownId]) // eslint-disable-line react-hooks/exhaustive-deps
  const open = ordered.filter((r) => r.judged && ['pending', 'partial', 'stale'].includes(r.judged.status)).length

  const allowed = cur?.item.allowed ?? DEFAULT_ALLOWED
  const decide = (kind: DecisionKind, message?: string) => {
    if (!cur?.hash || !cur.judged || cannotDecide(cur.item, cur.judged, reviewer) || !allowed.includes(kind)) return
    if (requireView && !receipts?.[cur.item.id]) return
    const d: Decision = { by: reviewer, decision: kind, at: clock.toISOString(), planHash: cur.hash, ...(message && (kind === 'respond' || kind === 'reject') ? { message } : {}) }
    setLocal((l) => ({ ...l, [cur.item.id]: [...(l[cur.item.id] ?? []), d] }))
    onDecide?.(cur.item.id, kind, cur.hash, d.message)
    if (onAction) {
      // The decision is bound to the plan and to what the reviewer saw beside it: the evidence, the risk and whether it can be undone.
      const { id, action, summary, requester, amountLabel, risk, plan, evidence, reversible, needs } = cur.item
      const planHash = cur.hash
      void viewDigest({ id, action, summary, requester, amountLabel, risk, plan, evidence, reversible, needs }).then((v) => onAction(decisionAction(id, kind, planHash, d.message, v, receipts?.[id])))
    }
  }
  const edit = (plan: unknown) => {
    if (!cur) return
    setEdits((e) => ({ ...e, [cur.item.id]: plan }))
    onEdit?.(cur.item.id, plan)
  }
  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).closest('input,textarea,button[role="treeitem"],.ol-json')) return
    const i = ordered.findIndex((r) => r.item.id === cur?.item.id)
    const k = e.key.toLowerCase()
    if (k === 'j' || e.key === 'ArrowDown') setSelected(ordered[Math.min(ordered.length - 1, i + 1)]?.item.id)
    else if (k === 'k' || e.key === 'ArrowUp') setSelected(ordered[Math.max(0, i - 1)]?.item.id)
    else if (k === 'a') decide('approve')
    else if (k === 'r') decide('reject')
    else if (k === 'e') decide('escalate')
    else return
    e.preventDefault()
  }

  const unseen = requireView && !!cur && !receipts?.[cur.item.id]
  const blocked = cur?.judged ? (cannotDecide(cur.item, cur.judged, reviewer) ?? (unseen ? 'What you are looking at has not been recorded as shown to you yet.' : null)) : 'Checking the plan…'
  const mine = cur?.judged?.valid.some((d) => d.by === reviewer)
  const hideOthers = blind && cur && !mine && cur.item.needs > 1 && reviewer !== cur.item.requester
  const left = cur?.item.expiresAt ? new Date(cur.item.expiresAt).getTime() - clock.getTime() : null

  return (
    <section role="group" className={cx('ol', className)} aria-label={title}>
      <div className="ol-head-row">
        <div>
          <h3 className="ol-title">{title}</h3>
          <div className="ol-sub">{open} waiting for a decision · you are {reviewer}</div>
        </div>
      </div>
      <div className="ol-queue-body" ref={body} tabIndex={0} onKeyDown={onKey} aria-label="Approval queue. J and K move, A approves, R rejects, E escalates.">
        <ul className="ol-list ol-qlist" role="listbox" aria-label="Requests">
          {ordered.map(({ item, judged }, idx) => {
            const s = judged ? STATUS_WORD[judged.status] : { text: 'Checking…' as string, tone: undefined }
            return (
              <li key={item.id} role="option" aria-selected={cur?.item.id === item.id} data-selected={cur?.item.id === item.id} className="ol-qitem ol-in" style={after(idx)} onClick={() => { setSelected(item.id); body.current?.focus() }}>
                <i className="ol-risk" data-risk={item.risk} aria-hidden="true" title={`${item.risk} risk`} />
                <span className="ol-sr">{item.risk} risk. </span>
                <div className="ol-qmain">
                  <div className="ol-qtitle"><b>{item.action}</b></div>
                  <div className="ol-sub ol-ell">{item.requester}{item.amountLabel ? ` · ${item.amountLabel}` : ''}</div>
                  <span className="ol-pill ol-mt-1" data-tone={s.tone}>{s.text}</span>
                </div>
              </li>
            )
          })}
        </ul>

        {cur && (
          <div className="ol-qdetail" aria-live="polite">
            <div className="ol-head-row ol-mb-1">
              <div>
                <strong className="ol-lead">{cur.item.action}</strong>
                <div className="ol-sub">Asked by {cur.item.requester}{cur.item.amountLabel ? ` · ${cur.item.amountLabel}` : ''} · {cur.item.risk} risk</div>
              </div>
              {cur.judged && <span className="ol-pill" data-tone={STATUS_WORD[cur.judged.status].tone}>{STATUS_WORD[cur.judged.status].text}</span>}
            </div>
            <p className="ol-my-2">{cur.item.summary}</p>
            {cur.judged && <p className="ol-statusline" data-status={cur.judged.status}>{cur.judged.reason}</p>}

            <div className="ol-qgrid">
              <div>
                <div className="ol-qhead">What will happen</div>
                <JsonTree value={cur.item.plan} label="plan" defaultExpandDepth={2} />
                <div className="ol-sub ol-mt-2"  title="Your approval is bound to this exact plan. If the plan changes, the approval stops counting.">
                  Bound to plan <b className="ol-id">{cur.hash ? cur.hash.slice(0, 12) : '…'}</b>
                </div>
              </div>
              <div>
                <div className="ol-qhead">Evidence checked</div>
                <ul className="ol-list ol-evidence">
                  {cur.item.evidence.map((e) => (
                    <li key={e.label} data-ok={e.ok}><span aria-hidden="true">{e.ok ? <Check /> : <Cross />}</span><span><span className="ol-sr">{e.ok ? 'Passed: ' : 'Failed: '}</span>{e.label}{e.detail && <span className="ol-sub"> · {e.detail}</span>}</span></li>
                  ))}
                </ul>
                <div className="ol-qhead ol-mt-4">If you approve</div>
                <p className="ol-chips">
                  {cur.item.reversible === false ? <span className="ol-pill" data-tone="bad">Cannot be undone</span> : <span className="ol-pill">{cur.item.reversible.undoUntil ? `Undo until ${formatWhen(cur.item.reversible.undoUntil)}` : 'Can be undone'}</span>}
                  {left !== null && <span className="ol-pill" data-tone={left > 0 ? 'warn' : 'bad'} title="If nobody decides in time it expires and nothing happens.">{left > 0 ? `Expires in ${formatDuration(left)}` : 'Expired'}</span>}
                </p>
              </div>
            </div>

            <div className="ol-qhead ol-mt-5">Approvals {cur.judged?.valid.filter((d) => d.decision === 'approve').length ?? 0} of {cur.item.needs}</div>
            {hideOthers ? <p className="ol-sub ol-mt-1">Other reviewers' decisions are hidden until you decide, so yours is your own judgement.</p> : (
              <ul className="ol-list ol-dlog">
                {cur.item.decisions.length === 0 && <li className="ol-sub">No decisions yet.</li>}
                {cur.item.decisions.map((d, i) => {
                  const bad = cur.judged?.ignored.find((x) => x.decision === d)
                  return <li key={i} data-ignored={!!bad}><b>{d.by}</b> {d.decision === 'approve' ? 'approved' : d.decision === 'reject' ? 'rejected' : d.decision === 'respond' ? 'answered' : 'escalated'} <span className="ol-sub">{formatWhen(d.at)}</span> <span className="ol-id ol-sub">{d.planHash.slice(0, 8)}</span>{d.message && <span className="ol-sub"> · "{d.message}"</span>}{bad && <span className="ol-ignored"> · does not count: {bad.why}</span>}</li>
                })}
              </ul>
            )}

            <ReviewActions key={cur.item.id + (cur.hash ?? '')} allowed={allowed} editable={!!cur.item.editable} approveLabel={cur.item.approveLabel ?? `Approve: ${cur.item.action}`} blocked={!!blocked} plan={cur.item.plan} onDecide={decide} onEdit={edit} />
            {blocked && <p className="ol-sub ol-mt-2">{blocked}</p>}
          </div>
        )}
      </div>
    </section>
  )
}

// Rules for an approval queue. The point of each: an approval must be about the exact thing that happens.
import { canonical, sha256Hex } from '../verify/canonical'

export type DecisionKind = 'approve' | 'reject' | 'escalate' | 'respond'
/** `message` is the reason for a rejection, or the reply when the decision is `respond`. */
export type Decision = { by: string; decision: DecisionKind; at: string; planHash: string; message?: string }
export type QueueItem = {
  id: string
  action: string
  summary: string
  requester: string
  amountLabel?: string
  risk: 'low' | 'medium' | 'high'
  /** The exact thing that will happen if this is approved. Its hash is what an approval is bound to. */
  plan: unknown
  expiresAt?: string
  evidence: { label: string; ok: boolean; detail?: string }[]
  /** `false` means it cannot be undone. */
  reversible: { undoUntil?: string } | false
  /** Approvals needed from different people. */
  needs: number
  decisions: Decision[]
  approveLabel?: string
  /** Which decisions the reviewer may make. Defaults to approve, reject and escalate. `respond` answers the agent instead of running the action. */
  allowed?: DecisionKind[]
  /** Lets the reviewer change the plan. Anyone's earlier approval of the old plan stops counting, so the edited plan needs its own. */
  editable?: boolean
}
export const DEFAULT_ALLOWED: DecisionKind[] = ['approve', 'reject', 'escalate']
export type ItemStatus = 'pending' | 'partial' | 'approved' | 'rejected' | 'escalated' | 'responded' | 'expired' | 'stale'
export type Judged = { status: ItemStatus; valid: Decision[]; ignored: { decision: Decision; why: string }[]; reason: string }

export const planDigest = (plan: unknown) => sha256Hex(canonical(plan))

/**
 * Works out where an item stands. A decision only counts if it was made on the plan as it is now, was made by
 * someone other than the requester, and is the first from that person. A person's earlier approval of an old
 * version of the plan never counts toward the new one.
 */
export function judgeItem(item: QueueItem, currentHash: string, now: Date): Judged {
  const valid: Decision[] = []
  const ignored: Judged['ignored'] = []
  const seen = new Set<string>()
  for (const d of item.decisions) {
    if (d.planHash !== currentHash) ignored.push({ decision: d, why: 'The plan changed after this decision, so it no longer counts.' })
    else if (d.by === item.requester) ignored.push({ decision: d, why: 'The person who asked cannot approve their own request.' })
    else if (seen.has(d.by)) ignored.push({ decision: d, why: 'This person already decided.' })
    else {
      seen.add(d.by)
      valid.push(d)
    }
  }
  const approvals = valid.filter((d) => d.decision === 'approve').length
  const staleApprovals = ignored.filter((i) => i.decision.decision === 'approve' && i.why.startsWith('The plan changed')).length
  const need = Math.max(1, item.needs)
  if (valid.some((d) => d.decision === 'reject')) return { status: 'rejected', valid, ignored, reason: 'A reviewer rejected this.' }
  if (valid.some((d) => d.decision === 'respond')) return { status: 'responded', valid, ignored, reason: 'A reviewer answered the agent instead. Nothing ran.' }
  if (approvals >= need) return { status: 'approved', valid, ignored, reason: `${approvals} of ${need} approvals, all on the current plan.` }
  if (valid.some((d) => d.decision === 'escalate')) return { status: 'escalated', valid, ignored, reason: 'Handed to someone with more authority.' }
  if (item.expiresAt && new Date(item.expiresAt).getTime() <= now.getTime()) return { status: 'expired', valid, ignored, reason: 'Nobody decided in time, so nothing happens.' }
  if (staleApprovals > 0) return { status: 'stale', valid, ignored, reason: `${staleApprovals} earlier ${staleApprovals === 1 ? 'approval was' : 'approvals were'} for a different version of the plan. Review it again.` }
  if (approvals > 0) return { status: 'partial', valid, ignored, reason: `${approvals} of ${need} approvals. ${need - approvals} more from a different person.` }
  return { status: 'pending', valid, ignored, reason: need > 1 ? `Needs ${need} approvals from different people.` : 'Waiting for a decision.' }
}

/** Why this person cannot decide right now, or null if they can. */
export function cannotDecide(item: QueueItem, judged: Judged, reviewer: string): string | null {
  if (judged.status === 'approved' || judged.status === 'rejected' || judged.status === 'escalated' || judged.status === 'responded') return 'This is already decided.'
  if (judged.status === 'expired') return 'This expired. Ask for it again.'
  if (reviewer === item.requester) return 'You asked for this, so someone else has to decide.'
  if (judged.valid.some((d) => d.by === reviewer)) return 'You have already decided on this plan.'
  return null
}

export const RISK_ORDER = { high: 0, medium: 1, low: 2 } as const
export const STATUS_ORDER: Record<ItemStatus, number> = { stale: 0, pending: 1, partial: 2, expired: 3, escalated: 4, responded: 5, approved: 6, rejected: 7 }

'use client'

import { useId, useState } from 'react'
import type { DecisionKind } from './approval'

export type ReviewActionsProps = {
  allowed: DecisionKind[]
  editable: boolean
  approveLabel: string
  blocked: boolean
  plan: unknown
  onDecide: (kind: DecisionKind, message?: string) => void
  onEdit: (plan: unknown) => void
}

/** The reviewer's buttons, the reason or reply field they share, and the plan editor. */
export function ReviewActions({ allowed, editable, approveLabel, blocked, plan, onDecide, onEdit }: ReviewActionsProps) {
  const base = useId()
  const [note, setNote] = useState('')
  const [noteError, setNoteError] = useState<string | null>(null)
  const [draft, setDraft] = useState<string | null>(null)
  const [draftError, setDraftError] = useState<string | null>(null)

  const decide = (kind: DecisionKind) => {
    const message = note.trim()
    if (kind === 'respond' && !message) { setNoteError('Write the reply first'); return }
    setNote('')
    setNoteError(null)
    onDecide(kind, message || undefined)
  }
  const save = () => {
    if (draft === null) return
    let parsed: unknown
    try { parsed = JSON.parse(draft) } catch (e) { setDraftError(`This is not valid JSON: ${(e as Error).message}`); return }
    if (JSON.stringify(parsed) === JSON.stringify(plan)) { setDraftError('Nothing changed.'); return }
    setDraft(null)
    setDraftError(null)
    onEdit(parsed)
  }

  if (draft !== null) {
    return (
      <div className="ol-editplan">
        <label className="ol-qhead" htmlFor={`${base}-plan`}>Edit the plan</label>
        <textarea id={`${base}-plan`} className="ol-textarea ol-mono" rows={Math.min(14, draft.split('\n').length + 1)} value={draft} spellCheck={false} onChange={(e) => { setDraft(e.target.value); setDraftError(null) }} aria-describedby={draftError ? `${base}-plan-err` : undefined} aria-invalid={!!draftError} />
        {draftError && <p id={`${base}-plan-err`} className="ol-sub ol-fielderr" role="alert">{draftError}</p>}
        <p className="ol-sub ol-mt-1"  title="Saving makes this a different plan, so earlier approvals stop counting.">A saved edit needs its own approval.</p>
        <div className="ol-actions">
          <button type="button" className="ol-btn" data-kind="approve" onClick={save}>Save the edited plan</button>
          <button type="button" className="ol-btn" onClick={() => { setDraft(null); setDraftError(null) }}>Cancel</button>
        </div>
      </div>
    )
  }
  return (
    <>
      {(allowed.includes('reject') || allowed.includes('respond')) && (
        <div className="ol-note">
          <label className="ol-qhead" htmlFor={`${base}-note`}>{allowed.includes('respond') ? 'Reason or reply' : 'Reason'}</label>
          <textarea id={`${base}-note`} className="ol-textarea" rows={2} value={note} disabled={blocked} onChange={(e) => { setNote(e.target.value); setNoteError(null) }} aria-invalid={!!noteError} aria-describedby={noteError ? `${base}-note-err` : undefined} placeholder="Goes to the agent" />
          {noteError && <p id={`${base}-note-err`} className="ol-sub ol-fielderr" role="alert">{noteError}</p>}
        </div>
      )}
      <div className="ol-actions">
        {allowed.includes('approve') && <button type="button" className="ol-btn" data-kind="approve" disabled={blocked} onClick={() => decide('approve')}>{approveLabel}<kbd>A</kbd></button>}
        {allowed.includes('reject') && <button type="button" className="ol-btn" data-kind="reject" disabled={blocked} onClick={() => decide('reject')}>Reject<kbd>R</kbd></button>}
        {allowed.includes('escalate') && <button type="button" className="ol-btn" disabled={blocked} onClick={() => decide('escalate')}>Escalate<kbd>E</kbd></button>}
        {allowed.includes('respond') && <button type="button" className="ol-btn" disabled={blocked} onClick={() => decide('respond')}>Reply without running</button>}
        {editable && <button type="button" className="ol-btn" disabled={blocked} onClick={() => { setDraft(JSON.stringify(plan, null, 2)); setDraftError(null) }}>Edit the plan</button>}
      </div>
    </>
  )
}
